<?php
namespace App\Http\Controllers;
use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;use Illuminate\Support\Facades\Storage;use App\Services\PeriodGuard;
class HomeworkController extends Controller{
 public function submit(Request $r,$lesson){$u=$r->user();abort_unless($u->student_id,403);$l=DB::table('lesson_occurrences')->find($lesson);abort_if(!$l,404);PeriodGuard::writable($l->academic_period_id);abort_unless($this->studentInGroup($u->student_id,$l),403);$d=$r->validate(['answer_text'=>'nullable|string|max:10000','file'=>'nullable|file|max:10240|mimes:pdf,doc,docx,xls,xlsx,ppt,pptx,txt,jpg,jpeg,png,zip']);abort_if(empty($d['answer_text'])&&!$r->hasFile('file'),422,'Добавьте текст ответа или файл.');$old=DB::table('homework_submissions')->where('lesson_occurrence_id',$lesson)->where('student_id',$u->student_id)->first();$path=$old?->file_path;$name=$old?->original_name;if($r->hasFile('file')){if($path)Storage::disk('local')->delete($path);$f=$r->file('file');$path=$f->store('homework/'.$lesson.'/'.$u->student_id,'local');$name=$f->getClientOriginalName();}DB::table('homework_submissions')->updateOrInsert(['lesson_occurrence_id'=>$lesson,'student_id'=>$u->student_id],['answer_text'=>$d['answer_text']??null,'file_path'=>$path,'original_name'=>$name,'status'=>'submitted','teacher_comment'=>null,'checked_by'=>null,'checked_at'=>null,'submitted_at'=>now(),'updated_at'=>now(),'created_at'=>$old?->created_at??now()]);return back()->with('success','Домашняя работа отправлена.');}
 public function review(Request $r,$submission){$s=DB::table('homework_submissions as h')->join('lesson_occurrences as l','l.id','=','h.lesson_occurrence_id')->where('h.id',$submission)->select('h.*','l.teacher_id','l.academic_period_id')->first();abort_if(!$s,404);PeriodGuard::writable($s->academic_period_id);abort_unless($r->user()->isSuperAdmin()||$r->user()->hasRole('admin')||($r->user()->teacher_id&&$r->user()->teacher_id==$s->teacher_id),403);$d=$r->validate(['status'=>'required|in:checked,revision','teacher_comment'=>'nullable|string|max:5000']);DB::table('homework_submissions')->where('id',$submission)->update(['status'=>$d['status'],'teacher_comment'=>$d['teacher_comment']??null,'checked_by'=>$r->user()->id,'checked_at'=>now(),'updated_at'=>now()]);return back()->with('success','Домашняя работа проверена.');}
 public function download(Request $r,$submission){$s=DB::table('homework_submissions as h')->join('lesson_occurrences as l','l.id','=','h.lesson_occurrence_id')->where('h.id',$submission)->select('h.*','l.teacher_id')->first();abort_if(!$s||!$s->file_path,404);$u=$r->user();abort_unless(($u->student_id&&$u->student_id==$s->student_id)||$u->isSuperAdmin()||$u->hasRole('admin')||($u->teacher_id&&$u->teacher_id==$s->teacher_id),403);abort_unless(Storage::disk('local')->exists($s->file_path),404);return Storage::disk('local')->download($s->file_path,$s->original_name?:'homework');}
 private function studentInGroup($sid,$l){$m=DB::table('student_group_memberships')->where('student_id',$sid)->where('academic_period_id',$l->academic_period_id)->first();if($m)return $m->study_group_id==$l->study_group_id&&$m->status==='active';return DB::table('students')->where('id',$sid)->where('current_group_id',$l->study_group_id)->where('status','active')->exists();}
}